CREATE TABLE media_type (id CLOB NOT NULL, bundle CLOB DEFAULT '' NOT NULL, label CLOB DEFAULT '' NOT NULL, langcode CLOB DEFAULT 'en' NOT NULL, _data CLOB DEFAULT '{}' NOT NULL, PRIMARY KEY (id))
CREATE INDEX media_type_bundle ON media_type (bundle)
CREATE TABLE menu (id CLOB NOT NULL, bundle CLOB DEFAULT '' NOT NULL, label CLOB DEFAULT '' NOT NULL, langcode CLOB DEFAULT 'en' NOT NULL, _data CLOB DEFAULT '{}' NOT NULL, PRIMARY KEY (id))
CREATE INDEX menu_bundle ON menu (bundle)
